// =====================
// 1) Read & normalize input
// =====================
const raw = items.map(i => i.json);

function parseMaybeWrappedJson(str) {
  if (typeof str !== 'string') return null;
  const cleaned = str.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  try { return JSON.parse(cleaned); } catch (_) { return null; }
}

let records = [];
if (raw.length === 1 && typeof raw[0].output === 'string') {
  const parsed = parseMaybeWrappedJson(raw[0].output);
  if (Array.isArray(parsed)) records = parsed;
}
if (records.length === 0) {
  records = raw; // already row-wise
}

const norm = (s) => (typeof s === 'string' ? s.trim() : (s ?? ''));

// =====================
// 2) Map directly to rows
// =====================
const rows = records.map(r => ({
  topic: norm(r.topic),
  pain_point: norm(r.pain_point),
  traditional_solution: norm(r.traditional_solution),
  ai_solution: norm(r.ai_solution),
  source_title: norm(r.source?.title || r.source_title || ''),
  source_quote: norm(r.source?.quote || r.source_quote || ''),
  source_url: norm(r.source?.url || r.source_url || ''),
  source_date: norm(r.source?.date || r.source_date || '')
}));

// =====================
// 3) Return as n8n items
// =====================
return rows.map(r => ({ json: r }));

const filtered = items
  .filter(item => {
    const expertise = item.json["Expertise_Areas"];
    const niche = item.json["Expertise_Niche"];
    return expertise && niche; // keep only if both exist
  })
  .map(item => {
    return {
      json: {
        Expertise_Areas: item.json["Expertise_Areas"],
        Expertise_Niche: item.json["Expertise_Niche"]
      }
    };
  });

// return only the first row (or empty array if none)
return filtered.length > 0 ? [filtered[0]] : [];

const parsedOutput = JSON.parse(items[0].json.output); // Parse the JSON string
const result = [];

parsedOutput.forEach(block => {
  const sources = block.sources || [];

  sources.forEach((source, index) => {
    result.push({
      json: {
        topic: index === 0 ? block.topic : '',
        pain_point: index === 0 ? block.pain_point : '',
        traditional_solution: index === 0 ? block.traditional_solution : '',
        ai_solution: index === 0 ? block.ai_solution : '',
        source_title: source.title || '',
        source_quote: source.quote || '',
        source_url: source.url || '',
        source_date: source.date || ''
      }
    });
  });
});

return result;

// Collect all items passed into this Code node
const inputItems = items.map(item => item.json);

// Extract expertise + niche from the first item (always present)
const expertise = inputItems[0]["Expertise Areas"] || inputItems[0]["['Expertise Areas']"] || "";
const niche = inputItems[0]["Expertise_Niche"] || inputItems[0]["Expertise_Niche"] || "";

// Filter out items that are just pillar info (no Blog_Title / Blog_Url etc.)
const clusters = inputItems.filter(obj =>
  obj.Blog_Title || obj.Blog_Url || obj["Blog_Summery "] || obj.Blog_Summery
);

// Normalize cluster fields
const normalizedClusters = clusters.map(c => ({
  Cluster_Number: c.Cluster_Number || c.Blog_Number || "",
  Blog_Title: c.Blog_Title || "",
  Blog_Summery: c["Blog_Summery "] || c.Blog_Summery || "",
  Blog_Url: c.Blog_Url || ""
}));

// Wrap everything under one parent key so you can pass it forward
return [
  {
    json: {
      cluster_context: {
        expertise,
        niche,
        clusters: normalizedClusters
      }
    }
  }
];

// Collect all topics into an array
const topics = items.map(item => item.json.topic || item.json.Blog_Title || "").filter(t => t);

// Return as a single row
return [
  {
    json: {
      new_topics: topics
    }
  }
];

// Collect all published topics into an array
const topics = items.map(item => item.json.Blog_Title || item.json.topic || "").filter(t => t);

// Return as a single row
return [
  {
    json: {
      published_topics: topics
    }
  }
];

// Normalize for safe comparison
function normalize(str) {
  return (str || "").toLowerCase().trim();
}

// 1) Separate rows and grab unique_new_topics
let filteredTitles = [];
const fullData = [];

for (const item of items) {
  const r = item.json;

  // Collect first non-empty unique_new_topics
  if (r.output) {
    try {
      const parsed = JSON.parse(r.output);
      if (parsed.unique_new_topics && !filteredTitles.length) {
        filteredTitles = parsed.unique_new_topics.map(normalize);
      }
    } catch (e) {}
  }

  // Collect the topic rows
  if (r.topic) {
    fullData.push(r);
  }
}

// 2) Filter rows by topic
const finalData = fullData.filter(d =>
  filteredTitles.includes(normalize(d.topic))
);

// 3) Return in n8n format
return finalData.map(d => ({ json: d }));

